using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Reflection;
using UnityEngine;
using UnityEngine.UIElements;
namespace MassiveArmy.Planetary {
    internal static class VehicleInteractionValidation {
        sealed class Carrier:IVehicleCarrier,IVehicleDeck,IVehicleInterior {
            public SpacePose pose;public Transform root;public string CarrierName=>"Moving test ship";public SpacePose CarrierPose=>pose;public IVehicleCarrier ParentCarrier=>null;public VehicleCarrierBay[] VehicleBays=>Array.Empty<VehicleCarrierBay>();public bool BoardingAvailable=>true;
            public bool Owns(Collider c)=>root!=null&&c!=null&&c.transform.IsChildOf(root);
            public bool SampleVehicleDeck(Double3 point,out VehicleGroundContact contact){var local=Double3.Rotate(Quaternion.Inverse(pose.rotation),point-pose.position).Float;contact=new VehicleGroundContact{position=pose.position+Double3.Rotate(pose.rotation,new Double3(local.x,0,local.z)),normal=pose.rotation*Vector3.up};return Mathf.Abs(local.x)<=5&&Mathf.Abs(local.z)<=3&&local.y>=-1.2f;}
            public bool FitsVehicle(VehicleDefinition d,SpacePose p){var local=Double3.Rotate(Quaternion.Inverse(pose.rotation),p.position-pose.position).Float;return Mathf.Abs(local.x)+d.size.x*.5f<5&&Mathf.Abs(local.z)+d.size.z*.5f<3;}
        }
        [Serializable]sealed class Row {public string name;public double medianMs,p95Ms,updatesPerSecond;public long unityAllocated,unityReserved;}
        [Serializable]sealed class Report {public string scope="Four bounded vehicle collision sweeps, in an isolated standalone fixture. CPU operation time; not whole-game frames or an army/fog performance acceptance run.";public List<Row> rows=new List<Row>();}
        internal static void Run(Action<bool,string> check){
            check(VehicleMotor.LocalStepDuration(1/60f)==1/60f&&VehicleMotor.LocalStepDuration(.2f)==.05f,"Ship and local vehicles share a real-time, hitch-bounded physics step independent of RTS speed");
            var baseSelection=(PlanetRtsBase)System.Runtime.Serialization.FormatterServices.GetUninitializedObject(typeof(PlanetRtsBase));var tile=new SettlementLandTile{id=1,kind=SettlementLandKind.Park};baseSelection.SelectLandTile(tile);check(baseSelection.SelectedLandTile==tile,"A park tile can become the sole inspection selection");baseSelection.SelectCitizen(new ColonyState(),new ResidentState{id=7});check(baseSelection.SelectedLandTile==null&&baseSelection.SelectedCitizen?.id==7,"Citizen inspection replaces the tile selection");baseSelection.SelectLandTile(new SettlementLandTile{kind=SettlementLandKind.Farm});check(baseSelection.SelectedCitizen==null&&baseSelection.SelectedLandTile.kind==SettlementLandKind.Farm,"Farm selection replaces citizen inspection");baseSelection.ClearSelection();check(baseSelection.SelectedLandTile==null,"Deselecting terrain clears the farm/park inspector");
            var parent=new VisualElement();using(var hud=new PersonalGameplayHud(null,parent)){for(int i=0;i<10;i++){var slot=parent.Q<Button>("personal-slot-"+i);check(slot!=null&&!slot.focusable&&slot.tabIndex<0,"Action slot "+i+" does not receive WASD focus navigation");}}
            foreach(double scale in new[]{1.0,10,100,1000}){double radius=60000*scale,mu=9.81*radius*radius;var orbit=PlanetOrbit.Calculate(new Double3(radius*1.1,0,0),new Double3(0,Math.Sqrt(mu/(radius*1.1)),0),mu);double horizon=GalaxyPrediction.ScaledHorizon(1800,radius);check(orbit.Bound&&horizon>=orbit.Period,"Forecast cap covers a representative full circular orbit at "+scale+"x scale");}check(Math.Abs(GalaxyPrediction.ScaledHorizon(1800,60000000)/1800-Math.Sqrt(1000))<1e-8&&GalaxyPrediction.Samples==160,"Large-planet forecasting scales its time span without increasing sample count");
            var planet=ScriptableObject.CreateInstance<PlanetDefinition>();planet.radius=120000000;planet.terrainHeight=0;planet.gravitationalParameter=0;var surface=new PlanetSurface(planet);var origin=new Double3(0,planet.radius,0);var terrain=new VehicleTerrainContact(surface,p=>(p-origin).Float,p=>origin+new Double3(p));
            var definition=ScriptableObject.CreateInstance<VehicleDefinition>();definition.size=Vector3.one;definition.chassisCentre=Vector3.up*.5f;definition.chassisSize=Vector3.one;definition.locomotion=VehicleLocomotion.Wheeled;definition.seats=new[]{new VehicleSeatDefinition()};definition.wheels=new[]{new VehicleWheelDefinition{position=new Vector3(-.4f,.2f,-.4f),radius=.2f},new VehicleWheelDefinition{position=new Vector3(.4f,.2f,-.4f),radius=.2f},new VehicleWheelDefinition{position=new Vector3(-.4f,.2f,.4f),radius=.2f},new VehicleWheelDefinition{position=new Vector3(.4f,.2f,.4f),radius=.2f}};
            var root=new GameObject("Moving carrier collision fixture");root.transform.position=new Vector3(20,10,0);foreach(float x in new[]{-3f,3f}){var wall=GameObject.CreatePrimitive(PrimitiveType.Cube);wall.transform.SetParent(root.transform,false);wall.transform.localPosition=new Vector3(x,1,0);wall.transform.localScale=new Vector3(.2f,3,10);}Physics.SyncTransforms();
            var previous=new SpacePose{position=origin+new Double3(0,10,0),rotation=Quaternion.identity,linearVelocity=new Double3(1200,0,0)};var current=previous;current.position+=new Double3(20,0,0);var carrier=new Carrier{pose=current,root=root.transform};var point=previous.position+new Double3(0,.025,0);
            terrain.MovingCarrier=carrier;terrain.PreviousCarrierPose=previous;var delta=new Vector3(20,0,-.1f);var allowed=terrain.Sweep(point,Quaternion.identity,definition,delta,out var normal,true);check((allowed-delta).magnitude<.001f,"A departing vehicle inherits ship translation without sweeping through the ship's previous wall position");
            allowed=terrain.Sweep(point,Quaternion.identity,definition,new Vector3(25,0,0),out normal,true);check(allowed.x>21&&allowed.x<23&&normal.x<-.5f,"Relative movement still collides with the moving carrier side wall");check(Math.Abs(terrain.ObstacleVelocity(point).x-1200)<.001,"Moving-wall collision uses carrier point velocity");
            var motor=new WheeledVehicleMotor(definition);motor.Release(new SpacePose{position=point,rotation=Quaternion.identity,linearVelocity=new Double3(1500,0,0)});motor.StepFlight(1/60f,terrain);check(Math.Abs(motor.Pose.linearVelocity.x-1200)<.01,"Wall response removes relative impact speed without deleting inherited ship velocity");
            var report=new Report();var hits=new RaycastHit[32];void OldSweeps(){for(int i=0;i<4;i++)Physics.BoxCastNonAlloc((point-origin).Float+Vector3.up*.5f,Vector3.one*.48f,delta.normalized,hits,Quaternion.identity,delta.magnitude+.04f,Physics.DefaultRaycastLayers,QueryTriggerInteraction.Ignore);}
            void RevisedSweeps(){for(int i=0;i<4;i++)terrain.Sweep(point,Quaternion.identity,definition,delta,out _,true);}
            Measure(report,"Previous four static-hull box casts",OldSweeps);Measure(report,"Four moving-carrier sweeps",RevisedSweeps);
            var ownRoot=new GameObject("Vehicle self-collision fixture");ownRoot.transform.position=(point-origin).Float;var body=GameObject.CreatePrimitive(PrimitiveType.Cube);body.transform.SetParent(ownRoot.transform,false);body.transform.localPosition=Vector3.up*.5f;var wheel=GameObject.CreatePrimitive(PrimitiveType.Cube);wheel.transform.SetParent(ownRoot.transform,false);wheel.transform.localPosition=new Vector3(0,.3f,-.8f);wheel.transform.localScale=Vector3.one*.4f;Physics.SyncTransforms();terrain.MovingCarrier=null;terrain.IgnoredCollider=body.GetComponent<Collider>();terrain.IgnoredRoot=ownRoot.transform;
            var selfMotion=terrain.Sweep(point,Quaternion.identity,definition,Vector3.back);check((selfMotion-Vector3.back).magnitude<.001f,"Vehicle sweeps ignore sibling wheel/interior colliders under their own rig root");check((terrain.RecoverPenetration(point,Quaternion.identity,definition)-point).Magnitude<.001,"Penetration recovery does not push the chassis away from its own wheels");ownRoot.SetActive(false);terrain.IgnoredCollider=null;terrain.IgnoredRoot=null;UnityEngine.Object.Destroy(ownRoot);
            root.SetActive(false);Physics.SyncTransforms();terrain.MovingCarrier=null;carrier=new Carrier{pose=new SpacePose{position=origin+new Double3(1000,10,0),rotation=Quaternion.identity,linearVelocity=new Double3(1200,0,0)}};
            planet.gravitationalParameter=9.81*planet.radius*planet.radius;var initial=VehicleParking.Resolve(carrier,new Vector3(0,.025f,0),Quaternion.identity);var controller=new VehicleController(null,terrain,null,definition,1,initial);controller.Seats.TryEnterPlayer(0);controller.Parking.Restore(carrier,-1,new Vector3(0,.025f,0),Quaternion.identity);
            bool departed=false;double releaseSpeed=0;for(int i=0;i<240;i++){carrier.pose.position+=carrier.pose.linearVelocity*(1/60.0);controller.Tick(1/60f,new VehicleInput{movement=new Vector2(0,-1)},controller.Parking.Carrier);if(!controller.Parking.Parked&&!departed){departed=true;releaseSpeed=controller.Motor.Pose.linearVelocity.x;}}
            check(departed&&Math.Abs(releaseSpeed-1200)<5,"Driving through a moving deck exit at 1000x planet radius adds the carrier velocity exactly once");check(!controller.Parking.Parked&&controller.Motor.Pose.position.z< -5,"Vehicle continues away from the open exit instead of snapping back into the carrier");check(controller.Motor.Pose.position.Magnitude>=surface.ProjectToSurface(controller.Motor.Pose.position).Magnitude-.001,"Airborne departure remains above the analytic terrain floor");
            var rotated=current;rotated.rotation=Quaternion.Euler(0,90,0);var carried=VehicleParking.TransportPoint(previous,rotated,previous.position+new Double3(0,0,2));check((carried-(rotated.position+new Double3(2,0,0))).Magnitude<.001,"Carrier transport rotates precise offsets without a world-origin jump");
            var args=Environment.GetCommandLineArgs();int at=Array.IndexOf(args,"-planet-output");string output=at>=0?args[at+1]:"TestResults/VehicleInteraction/Run";Directory.CreateDirectory(output);File.WriteAllText(Path.Combine(output,"vehicle-sweeps.json"),JsonUtility.ToJson(report,true));UnityEngine.Object.Destroy(root);UnityEngine.Object.Destroy(definition);UnityEngine.Object.Destroy(planet);
        }
        static void Measure(Report report,string name,Action operation){operation();var samples=new double[120];double total=0;for(int i=0;i<samples.Length;i++){long start=Stopwatch.GetTimestamp();operation();samples[i]=(Stopwatch.GetTimestamp()-start)*1000d/Stopwatch.Frequency;total+=samples[i];}Array.Sort(samples);report.rows.Add(new Row{name=name,medianMs=samples[60],p95Ms=samples[113],updatesPerSecond=samples.Length*1000/total,unityAllocated=UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong(),unityReserved=UnityEngine.Profiling.Profiler.GetTotalReservedMemoryLong()});}
    }
}
